242	// send POSTs the event to the endpoint and returns the response status and, when it failed, why.
243	func (s *Service) send(ctx context.Context, ep store.WebhookEndpoint, e store.Event) (int, string) {
244		body, err := json.Marshal(Body{ID: e.ID, Type: e.Type, CreatedAt: e.CreatedAt, Data: e.Data})
245		if err != nil {
246			return 0, err.Error()
247		}
248		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
249		defer cancel()
250		// The host may resolve to other addresses than when the URL was saved, so it is checked again before every attempt.
251		u, err := url.Parse(ep.URL)
252		if err != nil {
253			return 0, err.Error()
254		}
255		if err := s.publicHost(ctx, u.Hostname()); err != nil {
256			return 0, err.Error()
257		}
258		req, err := http.NewRequestWithContext(ctx, http.MethodPost, ep.URL, bytes.NewReader(body))
259		if err != nil {
260			return 0, err.Error()
261		}
262		req.Header.Set("Content-Type", "application/json")
263		req.Header.Set("User-Agent", "Tally-Webhooks/1.0")
264		req.Header.Set("Tally-Event-Id", e.ID)
265		req.Header.Set("Tally-Event-Type", e.Type)
266		req.Header.Set("Tally-Signature", Sign(ep.Secret, body))
267		resp, err := s.doer.Do(req)
268		if err != nil {
269			return 0, err.Error()
270		}
271		defer resp.Body.Close()
272		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 64<<10))
273		if resp.StatusCode < 200 || resp.StatusCode > 299 {
274			return resp.StatusCode, fmt.Sprintf("the endpoint answered %d", resp.StatusCode)
275		}
276		return resp.StatusCode, ""
277	}
